package app.kinnect.live;
import android.app.*;import android.animation.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;
/** Visual feedback only for confirmed success; errors and decisions remain readable. */
final class SuccessEffects {
 private static final java.util.Map<Activity,View> active=new java.util.WeakHashMap<>();
 static boolean message(Activity a,String text){if(text==null)return false;String s=text.toLowerCase(java.util.Locale.ROOT);boolean yes=s.startsWith("đã đăng bài")||s.startsWith("đã đăng video")||s.startsWith("đã gửi lời mời")||s.startsWith("đã kết bạn")||s.startsWith("đã gửi báo cáo")||s.startsWith("đã lưu")||s.startsWith("đã áp dụng")||s.startsWith("đã sao chép")||s.startsWith("đã cập nhật")||s.startsWith("đã tặng xu")||s.startsWith("saved")||s.startsWith("applied")||s.startsWith("copied")||s.equals("coins granted");if(!yes)return false;a.runOnUiThread(()->small(a,text,s.contains("sao chép")||s.contains("copied")?"copy":s.contains("tặng")?"gift":"check"));return true;}
 static void clear(Activity a){View prior=active.remove(a);if(prior!=null&&prior.getParent() instanceof ViewGroup)((ViewGroup)prior.getParent()).removeView(prior);}
 static void small(Activity a,String announcement,String icon){if(a.isFinishing()||a.isDestroyed())return;clear(a);CommerceUi ui=new CommerceUi(a);FrameLayout root=(FrameLayout)a.getWindow().getDecorView();FrameLayout orb=new FrameLayout(a);orb.setTag("feedback:success");orb.setBackground(ui.round(ui.purple,99));ImageView mark=new ImageView(a);mark.setImageDrawable(ui.glyph(icon,Color.WHITE,28));orb.addView(mark,new FrameLayout.LayoutParams(ui.dp(28),ui.dp(28),Gravity.CENTER));FrameLayout.LayoutParams at=new FrameLayout.LayoutParams(ui.dp(60),ui.dp(60),Gravity.TOP|Gravity.CENTER_HORIZONTAL);at.topMargin=ui.dp(104);root.addView(orb,at);active.put(a,orb);orb.announceForAccessibility(I18n.t(announcement));orb.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);if(ValueAnimator.areAnimatorsEnabled()){orb.setScaleX(.65f);orb.setScaleY(.65f);orb.setAlpha(0);orb.animate().alpha(1).scaleX(1).scaleY(1).setDuration(220).start();}orb.postDelayed(()->{if(active.get(a)==orb){orb.animate().alpha(0).setDuration(180).withEndAction(()->clear(a)).start();}},1100);}
 static void purchase(Activity a,JSONObject product,Runnable use){if(a.isFinishing()||a.isDestroyed())return;clear(a);CommerceUi ui=new CommerceUi(a);FrameLayout decor=(FrameLayout)a.getWindow().getDecorView();FrameLayout overlay=new FrameLayout(a);overlay.setTag("feedback:purchase");overlay.setBackgroundColor(0xcc111022);overlay.setClickable(true);LinearLayout card=ui.col();card.setGravity(Gravity.CENTER);card.setPadding(ui.dp(24),ui.dp(18),ui.dp(24),ui.dp(18));FrameLayout.LayoutParams layout=new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER);layout.setMargins(ui.dp(16),0,ui.dp(16),0);StorePackageDesign.Art art=new StorePackageDesign.Art(a,product);card.addView(art,new LinearLayout.LayoutParams(-1,ui.dp(170)));ImageView tick=new ImageView(a);tick.setImageDrawable(ui.glyph("check",Color.WHITE,38));LinearLayout.LayoutParams tickAt=new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48));tickAt.topMargin=ui.dp(16);card.addView(tick,tickAt);TextView title=ui.text(product.optString("name"),23,Color.WHITE,true);title.setGravity(Gravity.CENTER);ui.add(card,title,10);Button next=ui.action("Dùng ngay","arrow_up_right",()->{clear(a);if(use!=null)use.run();});ui.add(card,next,22);overlay.addView(card,layout);Spark spark=new Spark(a);overlay.addView(spark,new FrameLayout.LayoutParams(-1,-1));FrameLayout close=ui.icon("x","Đóng",()->clear(a));FrameLayout.LayoutParams x=new FrameLayout.LayoutParams(ui.dp(44),ui.dp(44),Gravity.TOP|Gravity.END);x.setMargins(0,ui.dp(64),ui.dp(18),0);overlay.addView(close,x);decor.addView(overlay,new FrameLayout.LayoutParams(-1,-1));active.put(a,overlay);overlay.announceForAccessibility(I18n.t("Mua thành công")+" · "+product.optString("name"));overlay.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);if(ValueAnimator.areAnimatorsEnabled()){card.setScaleX(.86f);card.setScaleY(.86f);card.setAlpha(0);card.animate().alpha(1).scaleX(1).scaleY(1).setDuration(420).start();spark.start();}overlay.postDelayed(()->{if(active.get(a)==overlay)clear(a);},4500);}
 static final class Spark extends View{final Paint p=new Paint(3);float phase;ValueAnimator anim;Spark(Activity a){super(a);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}void start(){anim=ValueAnimator.ofFloat(0,1);anim.setDuration(1600);anim.addUpdateListener(v->{phase=(Float)v.getAnimatedValue();invalidate();});anim.start();}protected void onDraw(Canvas c){super.onDraw(c);int[] colors={0xffc4b5fd,0xfff9a8d4,0xff67e8f9,0xfffde68a};for(int i=0;i<30;i++){double angle=i*2.39996;float distance=(.08f+phase*.55f)*getWidth(),x=getWidth()/2f+(float)Math.cos(angle)*distance,y=getHeight()*.44f+(float)Math.sin(angle)*distance+phase*phase*80;p.setColor(colors[i%4]);p.setAlpha((int)(255*(1-phase)));float radius=2+(i%3);c.drawCircle(x,y,radius*getResources().getDisplayMetrics().density,p);}}protected void onDetachedFromWindow(){if(anim!=null)anim.cancel();super.onDetachedFromWindow();}}
}
